/**
 * Linh hồn Frontend (Logic AJAX hiển thị) của local_exercise_suggestion
 * AMD Module chuẩn Moodle.
 *
 * @module local_exercise_suggestion/main
 */
define(['jquery', 'core/ajax', 'core/templates', 'core/notification'], function ($, Ajax, Templates, Notification) {

    /**
     * Hàm render Skeleton HTML (Hiệu ứng đang tải)
     * @param {Object} container The jQuery element
     */
    function showLoadingSkeleton(container) {
        var skeletonHtml = `
            <div class="exercise-suggestions-wrapper" style="opacity: 0.6;">
                <div class="suggestions-header" style="background:#e0e0e0; height: 100px; margin-bottom: 20px;">
                    <h2 style="color:#666">Đang phân tích dữ liệu AI...</h2>
                </div>
                <div class="exercises-grid">
                    <div class="exercise-card" style="height:150px; background:#f5f5f5; border:none;"></div>
                    <div class="exercise-card" style="height:150px; background:#f5f5f5; border:none;"></div>
                </div>
            </div>`;
        container.html(skeletonHtml);
    }

    return {
        /**
         * Hàm khởi tạo chính, được gọi từ trang Moodle
         */
        init: function () {
            $(document).ready(function () {
                // Lắng nghe sự kiện click trên nút "Gợi ý bài tập"
                $(document).on('click', '.btn-suggest-exercise', function (e) {
                    e.preventDefault();

                    var $btn = $(this);

                    // Nếu click lần 2 hoặc đã lấy rồi thì có thể lướt tới chỗ result hoặc toggle
                    var $container = $('#suggestion-results-container');

                    var courseId = $btn.data('courseid');
                    var sesskey = M.cfg.sesskey; // Lấy sesskey từ biến global của Moodle

                    // 1. Thay đổi UI để User biết hệ thống đang xử lý
                    var originalBtnText = $btn.html();
                    $btn.html('<i class="fa fa-spinner fa-spin"></i> Đang phân tích...').prop('disabled', true);

                    // Hiện khung loading skeleton ảo
                    showLoadingSkeleton($container);

                    // 2. Build cURL AJAX gọi tới ajax.php thay vì Ajax() của Moodle
                    // (bởi vì ta đang tạo file ajax.php thuần túy do Web Services hơi cồng kềnh cho task này)
                    $.ajax({
                        url: M.cfg.wwwroot + '/local/exercise_suggestion/ajax.php',
                        type: 'POST',
                        dataType: 'json',
                        data: {
                            sesskey: sesskey,
                            courseid: courseId
                        },
                        success: function (response) {
                            // Phản hồi thành công từ mạng (HTTP 200)
                            if (response.status === 'success') {
                                // 3. Gọi hàm Template render của Moodle (Mustache JS)
                                Templates.render('local_exercise_suggestion/suggestions_list', response.data)
                                    .done(function (html, js) {
                                        // Đổ HTML nhận được vào container
                                        $container.hide().html(html).fadeIn(500);
                                        // Load thêm JS của template nếu có
                                        Templates.runTemplateJS(js);

                                        // Trả lại UI cho nút bấm
                                        $btn.html('<i class="fa fa-check"></i> Đã có dữ liệu')
                                            .removeClass('btn-primary')
                                            .addClass('btn-success');

                                        // Cuộn trang mượt mà xuốgn chỗ Data
                                        $('html, body').animate({
                                            scrollTop: $container.offset().top - 50
                                        }, 800);
                                    })
                                    .fail(Notification.exception);
                            } else {
                                // Nếu code php trả về 'error' (Ví dụ bắt Try-Catch Exception)
                                Notification.addNotification({
                                    message: response.message || 'Lỗi không xác định từ Server.',
                                    type: 'error'
                                });
                                $btn.html(originalBtnText).prop('disabled', false);
                                $container.empty();
                            }
                        },
                        error: function (xhr) {
                            // HTTP Lỗi (400, 500)
                            var errorMsg = 'Lỗi kết nối đến máy chủ.';
                            if (xhr.responseJSON && xhr.responseJSON.message) {
                                errorMsg = xhr.responseJSON.message;
                            }

                            Notification.addNotification({
                                message: errorMsg,
                                type: 'error'
                            });

                            $btn.html(originalBtnText).prop('disabled', false);
                            $container.empty();
                        }
                    });
                });
            });
        }
    };
});
